//! M5-T3 acceptance: the multi-binary pass hands `core_ids` to the core pass.
//!
//! Since M5 the local -> global mapping is native to `rticx-core`: the
//! extension pass only *reads* it (through the core parser) and leaves the key
//! in the arguments, while `external_cores` stays pass-owned. A
//! `cores = 2, core_ids = [1, 2]` application must therefore compile without
//! an unknown-argument warning, and the runtime core checks generated by the
//! software-task pass must compare `current_core_id()` against the global ids.

use proc_macro2::TokenStream;
use quote::quote;
use rticx_core::RticMacroBuilder;
use rticx_core::mock_backend::MockCoreBackend;
use rticx_sw_pass::{SoftwarePass, SwPassBackend};
use rticx_xbin_pass::XbinPass;

/// A software-task backend whose `current_core_id()` is a test expression, so
/// the generated `spawn`/`cross_spawn` guards can be inspected.
struct TestSwBackend;

impl SwPassBackend for TestSwBackend {
    fn queue_path(&self) -> syn::Path {
        syn::parse_quote!(rticx::export::Queue)
    }

    fn generate_local_pend_fn(&self, _core: u32, mut empty_body_fn: syn::ItemFn) -> syn::ItemFn {
        empty_body_fn.block = Box::new(syn::parse_quote!({
            mock_local_pend(irq_nbr);
        }));
        empty_body_fn
    }

    fn generate_cross_pend_fn(
        &self,
        _core: u32,
        mut empty_body_fn: syn::ItemFn,
    ) -> Option<syn::ItemFn> {
        empty_body_fn.block = Box::new(syn::parse_quote!({
            mock_cross_pend(irq_nbr);
        }));
        Some(empty_body_fn)
    }

    fn current_core_id(&self) -> Option<syn::Expr> {
        Some(syn::parse_quote!(mock_current_core_id()))
    }
}

/// Macro arguments of the two-core application with a non-identity mapping:
/// local core 0 -> global 1, local core 1 -> global 2.
fn args() -> TokenStream {
    quote!(
        device = mypac,
        cores = 2,
        dispatchers = [[IRQ0], [IRQ1, IRQ2]],
        core_ids = [1, 2],
        external_cores = [3]
    )
}

/// A two-core application with a local software task per core and one
/// cross-core software task spawned from local core 0.
fn app() -> syn::ItemMod {
    syn::parse_quote! {
        mod app {
            #[init(core = 0)]
            fn init0() -> TaskInitsCore0 {
                TaskInitsCore0 {}
            }

            #[init(core = 1)]
            fn init1() -> TaskInitsCore1 {
                TaskInitsCore1 {}
            }

            #[sw_task(priority = 2, core = 0)]
            struct Local0;

            impl RticSwTask for Local0 {
                type SpawnInput = u32;
                fn exec(&mut self, _input: u32) {}
            }

            #[sw_task(priority = 3, core = 1, spawn_by = 0)]
            struct Cross;

            impl RticSwTask for Cross {
                type SpawnInput = u32;
                fn exec(&mut self, _input: u32) {}
            }

            #[sw_task(priority = 4, core = 1)]
            struct Local1;

            impl RticSwTask for Local1 {
                type SpawnInput = u32;
                fn exec(&mut self, _input: u32) {}
            }
        }
    }
}

#[test]
fn non_identity_core_ids_reach_the_runtime_core_checks() {
    let mut builder = RticMacroBuilder::new(MockCoreBackend);
    builder.bind_pre_core_pass(XbinPass::disabled());
    builder.bind_pre_core_pass(SoftwarePass::new(TestSwBackend));

    let code = builder.build_rtic_macro2(args(), app(), None).to_string();

    assert!(
        !code.contains("compile_error"),
        "the pipeline must accept `core_ids` natively:\n{code}"
    );
    assert!(
        !code.contains("rticx_warn_unknown_app_core_ids"),
        "`core_ids` must not warn as an unknown argument:\n{code}"
    );

    // Local core 0 -> global 1 (`spawn` of `Local0`, `cross_spawn` of `Cross`).
    assert!(
        code.contains("if mock_current_core_id () != 1 { return Err (input) ; }"),
        "the core-local spawn guard must use the global id:\n{code}"
    );
    assert!(
        code.contains("if mock_current_core_id () != 1 { return Err (Some (input)) ; }"),
        "the cross-core guard must use the spawn_by global id:\n{code}"
    );
    // Local core 1 -> global 2.
    assert!(
        code.contains("if mock_current_core_id () != 2 { return Err (input) ; }"),
        "the core-local spawn guard of local core 1 must use global 2:\n{code}"
    );
    assert!(
        !code.contains("mock_current_core_id () != 0"),
        "a local core literal leaked into a runtime core check:\n{code}"
    );
}
